(({F:e})=>{e.push({code:"es",week:{dow:0,doy:6},prevText:"Ant",nextText:"Sig",todayText:"Hoy",yearText:"Año",monthText:"Mes",weekTextLong:"Semana",weekTextShort:"Sm",dayText:"Día",listText:"Agenda",prevHint:"$0 antes",nextHint:"$0 siguiente",todayHint(e,t){return"day"===t?"Hoy":("week"===t?"Esta":"Este")+" "+e.toLocaleLowerCase()},viewHint(e,t){return"Vista "+("week"===t?"de la":"del")+" "+e.toLocaleLowerCase()},allDayText:"Todo\nel día",moreLinkText:"más",noEventsText:"No hay eventos para mostrar"})})(FullCalendar.Shared);